  1	import { useEffect, useMemo, useState } from "react";
  2	import { parseDice, rollDice, type Pack, type Table } from "@runlog/rules-schema";
  3	import { subjectLabel, type InputRequest, type RunState } from "@runlog/engine";
  4	import { Die } from "../dice/Die.tsx";
  5	import { DiceTray } from "../dice/DiceTray.tsx";
  6	import { toDisplayDice, type RolledDie } from "../rolling.ts";
  7	import { lineFor, tableLines } from "./tableLook.ts";
  8	import { TableLookList } from "./TableLookList.tsx";
  9	
 10	/**
 11	 * Answering whatever the engine is waiting on.
 12	 *
 13	 * The default path is a number pad for dice the player has just thrown on the
 14	 * desk. That ordering is deliberate: a roll you made yourself and typed in
 15	 * carries a weight that a number the machine produced for you does not, and
 16	 * the whole point of these games is that the result feels like it happened to
 17	 * you.
 18	 */
 19	
 20	export function RequestPanel({
 21	  request,
 22	  pack,
 23	  state,
 24	  onAnswer,
 25	  onCancel,
 26	}: {
 27	  request: InputRequest;
 28	  pack: Pack;
 29	  state: RunState;
 30	  onAnswer: (key: string, value: string | number | boolean, machineRolled?: boolean, dice?: RolledDie[], seed?: number) => void;
 31	  onCancel: () => void;
 32	}) {
 33	  return (
 34	    <section className="panel request">
 35	      <h3 className="sectionTitle">The game is waiting on you</h3>
 36	      {request.kind === "roll" && <RollRequest request={request} table={pack.tables[request.purpose] ?? null} onAnswer={onAnswer} />}
 37	      {request.kind === "ask" && (
 38	        <YesNo
 39	          label={request.question}
 40	          hint="Only you can see the work. Answer honestly; nothing checks this."
 41	          onAnswer={(v) => onAnswer(request.key, v)}
 42	        />
 43	      )}
 44	      {request.kind === "prompt" && <PromptRequest request={request} pack={pack} state={state} onAnswer={onAnswer} />}
 45	      {request.kind === "chooseTarget" && <ChooseTarget request={request} pack={pack} state={state} onAnswer={onAnswer} />}
 46	      <button className="ghost small" onClick={onCancel}>
 47	        Cancel this step
 48	      </button>
 49	    </section>
 50	  );
 51	}
 52	
 53	/** The number pad. Physical dice first, an in-app roll one tap away, and the table it is for one tap away too. */
 54	function RollRequest({
 55	  request,
 56	  table,
 57	  onAnswer,
 58	}: {
 59	  request: Extract<InputRequest, { kind: "roll" }>;
 60	  /** The table this roll is for, when it is a table's own roll rather than an action's. */
 61	  table: Table | null;
 62	  onAnswer: (key: string, value: number, machineRolled?: boolean, dice?: RolledDie[], seed?: number) => void;
 63	}) {
 64	  const [typed, setTyped] = useState("");
 65	  // The table, opened beside the pad. A line pressed puts its number on
 66	  // the pad; Enter is still the player's, so a forced number is chosen
 67	  // twice and typed once, and the log says typed.
 68	  const [tableOpen, setTableOpen] = useState(false);
 69	  /**
 70	   * A roll in flight: decided already, but not yet answered.
 71	   *
 72	   * The value is chosen the moment the button is pressed and the dice then
 73	   * settle onto it. Nothing is reported to the engine until they stop: a
 74	   * result that appears while they are still in the air answers the question
 75	   * before the throw has finished asking it.
 76	   */
 77	  const [thrown, setThrown] = useState<{ total: number; dice: RolledDie[]; seed: number } | null>(null);
 78	  // The dice have stopped. The number is decided the moment the button is
 79	  // pressed, but it is not shown until they land: a total beside dice
 80	  // still tumbling takes the roll's one moment of suspense away.
 81	  const [settled, setSettled] = useState(false);
 82	  const [rollId, setRollId] = useState(0);
 83	
 84	  const dice = useMemo(() => {
 85	    try {
 86	      return parseDice(request.dice);
 87	    } catch {
 88	      return null;
 89	    }
 90	  }, [request.dice]);
 91	
 92	  // Reset between questions, so an answer cannot be carried into the next one.
 93	  useEffect(() => {
 94	    setTyped("");
 95	    setThrown(null);
 96	    setSettled(false);
 97	  }, [request.key]);
 98	
 99	  // Once the dice have landed, the number shows and is read for a beat
100	  // before the answer goes in and the receipt takes the panel's place.
101	  useEffect(() => {
102	    if (!settled || !thrown) return;
103	    const timer = window.setTimeout(() => onAnswer(request.key, thrown.total, true, thrown.dice, thrown.seed), 700);
104	    return () => window.clearTimeout(timer);
105	    // eslint-disable-next-line react-hooks/exhaustive-deps
106	  }, [settled]);
107	
108	  const value = Number(typed);
109	  const inRange = dice ? value >= dice.min && value <= dice.max : typed.length > 0;
110	  const ok = typed.length > 0 && inRange;
111	  const lines = useMemo(() => (table ? tableLines(table, dice) : []), [table, dice]);
112	  const landing = table && ok ? lineFor(lines, table, value) : null;
113	
114	  const submit = () => ok && onAnswer(request.key, value);
115	
116	  return (
117	    <div className="rollRequest">
118	      <p className="askLabel">
119	        {request.label ?? `Roll ${request.dice}`}
120	        <span className="muted">: {request.dice}</span>
121	      </p>
122	
123	      <div className={`padRow${thrown ? " rolling" : ""}`}>
124	        <input
125	          className="rollInput"
126	          inputMode="numeric"
127	          autoFocus
128	          value={typed}
129	          placeholder={dice ? `${dice.min}-${dice.max}` : "result"}
130	          onChange={(e) => setTyped(e.target.value.replace(/[^0-9]/g, ""))}
131	          onKeyDown={(e) => e.key === "Enter" && submit()}
132	          aria-label={`Result of ${request.dice}`}
133	        />
134	        <button className="primary" disabled={!ok || !!thrown} onClick={submit}>
135	          Enter
136	        </button>
137	        <button
138	          className="ghost"
139	          disabled={!!thrown}
140	          onClick={() => {
141	            // A convenience, not the default -- and flagged as machine-rolled,
142	            // so the log never claims you threw a die you did not throw.
143	            if (!dice) return;
144	            const { total, dice: values } = rollDice(request.dice, Math.random);
145	            // The value is decided here; the seed is only how the dice fly.
146	            setSettled(false);
147	            setThrown({ total, dice: toDisplayDice(request.dice, values, total), seed: Math.floor(Math.random() * 4294967296) });
148	            setRollId((n) => n + 1);
149	          }}
150	        >
151	          {thrown ? "Rolling…" : "Roll for me"}
152	        </button>
153	        {lines.length > 0 && (
154	          <button
155	            className={`ghost ${tableOpen ? "on" : ""}`}
156	            aria-expanded={tableOpen}
157	            onClick={() => setTableOpen((o) => !o)}
158	            title="See the lines this roll can land on"
159	          >
160	            Table
161	          </button>
162	        )}
163	      </div>
164	
165	      {tableOpen && table && (
166	        <TableLookList table={table} lines={lines} landing={landing} disabled={!!thrown} onPick={(v) => setTyped(String(v))} />
167	      )}
168	
169	      {thrown && (
170	        <div className="throw">
171	          <DiceTray dice={thrown.dice} rollId={rollId} seed={thrown.seed} onSettled={() => setSettled(true)} />
172	          <div className={`rollTotal ${settled ? "" : "pending"}`} aria-live="polite">
173	            <span className="big">{settled ? thrown.total : "…"}</span>
174	            <span className="how">{request.dice}</span>
175	          </div>
176	        </div>
177	      )}
178	
179	      {typed.length > 0 && !inRange && dice && (
180	        <p className="warnText">
181	          {request.dice} can only produce {dice.min}-{dice.max}.
182	        </p>
183	      )}
184	    </div>
185	  );
186	}
187	
188	function YesNo({ label, hint, onAnswer }: { label: string; hint?: string; onAnswer: (v: boolean) => void }) {
189	  return (
190	    <div>
191	      <p className="askLabel">{label}</p>
192	      {hint && <p className="muted small">{hint}</p>}
193	      <div className="padRow">
194	        <button className="primary" onClick={() => onAnswer(true)}>
195	          Yes
196	        </button>
197	        <button className="ghost" onClick={() => onAnswer(false)}>
198	          No
199	        </button>
200	      </div>
201	    </div>
202	  );
203	}
204	
205	function PromptRequest({
206	  request,
207	  pack,
208	  state,
209	  onAnswer,
210	}: {
211	  request: Extract<InputRequest, { kind: "prompt" }>;
212	  pack: Pack;
213	  state: RunState;
214	  onAnswer: (key: string, value: string | number | boolean) => void;
215	}) {
216	  const [text, setText] = useState("");
217	  useEffect(() => setText(""), [request.key]);
218	
219	  if (request.promptKind === "confirm") {
220	    return <YesNo label={request.label} onAnswer={(v) => onAnswer(request.key, v)} />;
221	  }
222	
223	  if (request.promptKind === "chooseSubject") {
224	    const candidates = state.subjects.filter((s) => !s.removed && (!request.eligibleOnly || s.finalized));
225	    return (
226	      <div>
227	        <p className="askLabel">{request.label}</p>
228	        <div className="options">
229	          {candidates.map((s) => (
230	            <button key={s.id} className="choice" onClick={() => onAnswer(request.key, s.id)}>
231	              <strong>#{s.id}</strong> {subjectLabel(pack, s)}
232	            </button>
233	          ))}
234	        </div>
235	      </div>
236	    );
237	  }
238	
239	  if (request.promptKind === "chooseValue" || request.promptKind === "chooseState") {
240	    const options = request.options ?? Object.entries(pack.states ?? {}).map(([id, s]) => `${id}|${s.label}`);
241	    return (
242	      <div>
243	        <p className="askLabel">{request.label}</p>
244	        <div className="options">
245	          {options.map((o) => {
246	            const [value, label] = o.includes("|") ? o.split("|") : [o, o];
247	            return (
248	              <button key={value} className="choice" onClick={() => onAnswer(request.key, value!)}>
249	                {label}
250	              </button>
251	            );
252	          })}
253	        </div>
254	      </div>
255	    );
256	  }
257	
258	  return (
259	    <div>
260	      <p className="askLabel">{request.label}</p>
261	      <div className="padRow">
262	        <input
263	          className="textInput"
264	          autoFocus
265	          value={text}
266	          onChange={(e) => setText(e.target.value)}
267	          onKeyDown={(e) => e.key === "Enter" && text && onAnswer(request.key, text)}
268	        />
269	        <button className="primary" disabled={!text} onClick={() => onAnswer(request.key, text)}>
270	          Enter
271	        </button>
272	      </div>
273	    </div>
274	  );
275	}
276	
277	function ChooseTarget({
278	  request,
279	  pack,
280	  state,
281	  onAnswer,
282	}: {
283	  request: Extract<InputRequest, { kind: "chooseTarget" }>;
284	  pack: Pack;
285	  state: RunState;
286	  onAnswer: (key: string, value: number) => void;
287	}) {
288	  return (
289	    <div>
290	      <p className="askLabel">{request.label}</p>
291	      <p className="muted small">The rules hand you this one. Choose from the {request.eligible.length} still eligible.</p>
292	      <div className="options">
293	        {request.eligible.map((id) => {
294	          const subject = state.subjects.find((s) => s.id === id);
295	          return (
296	            <button key={id} className="choice" onClick={() => onAnswer(request.key, id)}>
297	              <strong>#{id}</strong> {subject ? subjectLabel(pack, subject) : ""}
298	            </button>
299	          );
300	        })}
301	      </div>
302	    </div>
303	  );
304	}
305	
306	/** A small die used as a decoration next to a pending roll. */
307	export function RollHint({ dice }: { dice: string }) {
308	  try {
309	    const { faces } = parseDice(dice);
310	    return <Die faces={faces} display="?" />;
311	  } catch {
312	    return null;
313	  }
314	}

