 33	 * names itself and who sent it, so two decks racing for the same button
 34	 * each move it once, and one deck retried after an answer that never
 35	 * arrived moves it only once.
 36	 *
 37	 * Not total, though: an `act` may throw, most likely a write raced by
 38	 * another device. That still spends the ref and settles a verdict --
 39	 * the deck is told the press failed rather than left waiting on one
 40	 * that will never answer.
 41	 */
 42	export function takePress(press: Press, at: { seq: number; offer: Offer; seen: Map<string, Verdict> }, act: Acts): Verdict {
 43	  const key = `${press.from}:${press.ref}`;
 44	  const already = at.seen.get(key);
 45	  if (already) return already;
 46	
 47	  const settle = (verdict: Verdict): Verdict => {
 48	    at.seen.set(key, verdict);
 49	    return verdict;
 50	  };
 51	
 52	  if (press.seq !== at.seq) return settle({ ok: false, say: "That moved on." });
 53	
 54	  /**
 55	   * Taking the press itself: a throw is still a press taken, not one left
 56	   * hanging. In the act's own words where it threw any, because an act is
 57	   * the only thing that can see why -- a list still wanting the page, say.
 58	   */
 59	  const take = (fn: () => void): Verdict => {
 60	    try {
 61	      fn();
 62	      return { ok: true };
 63	    } catch (e) {
 64	      const said = e instanceof Error ? e.message.trim() : "";
 65	      return { ok: false, say: said === "" ? "That press failed." : said };
 66	    }
 67	  };
 68	
 69	  switch (press.press) {
 70	    case "primary": {
 71	      if (!at.offer.primary) return settle({ ok: false, say: at.offer.needsPage ?? "There is nothing to press." });
 72	      return settle(take(() => act.primary()));
 73	    }
 74	    case "move": {
 75	      const id = press.move ?? "";
 76	      if (!at.offer.moves.some((m) => m.id === id)) return settle({ ok: false, say: "That is not on offer." });
 77	      return settle(take(() => act.move(id)));
 78	    }
 79	    case "undo": {
 80	      if (!at.offer.undo) return settle({ ok: false, say: "There is nothing to take back." });
 81	      return settle(take(() => act.undo()));
 82	    }
 83	    case "answer": {
 84	      // Play on under a different setup: the page's own picker and its
 85	      // "Hand it out" in one press, which is what a key on a deck is for.
 86	      // It rides in the answer because that is the only field of a press
 87	      // the server passes through, and it names a setup by id, so it is
 88	      // checked against the offer the way a move is.
 89	      const named = press.answer?.["setup"];
 90	      if (typeof named === "string") {
 91	        if (!at.offer.setups.some((s) => s.id === named)) return settle({ ok: false, say: "That setup is not here." });
 92	        return settle(take(() => act.setup(named)));
 93	      }
 94	      // Tick everything this step waits for and press its own button. The
 95	      // offer says whether there is a list to tick; the act says whether
 96	      // one of its boxes is beyond a deck, and throws its own words if so.
 97	      if (press.answer?.["ticks"] === "all") {
 98	        if (!at.offer.presets.some((p) => p.kind === "checklist")) return settle({ ok: false, say: "The run is not asking for that." });
 99	        return settle(take(() => act.answer({ ticks: "all" })));
100	      }
101	      if (!at.offer.presets.some((p) => p.kind === "declareSubject")) return settle({ ok: false, say: "The run is not asking for that." });
102	      if (String(press.answer?.["subject"] ?? "").trim() === "") return settle({ ok: false, say: "That answer was empty." });
103	      return settle(take(() => act.answer(press.answer!)));
104	    }
105	    default:
