 15	/**
 16	 * The offer rides along with the snapshot.
 17	 *
 18	 * `RunView` publishes to the server through `useApi()`, a hook rather than a
 19	 * prop, so it is mocked module-wide the way `ChatPanel.test.tsx` mocks it.
 20	 * The run itself is a real, hydrated one-event log in a memory store: the
 21	 * engine's own `reduce` has to accept it, so this is the shortest log that
 22	 * does. `bench` keeps the race, asks and members panels off the tree; none
 23	 * of the three touch the offer, and each would otherwise want its own slice
 24	 * of the API double.
 25	 */
 26	
 27	const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..");
 28	const loaded = loadPackText(readFileSync(join(repoRoot, "packs/demo/pack.yaml"), "utf8"), "yaml");
 29	if (!loaded.ok) throw new Error("the demo pack did not load");
 30	const kiln = loaded.pack;
 31	const mode = Object.keys(kiln.modes)[0]!;
 32	
 33	const current: { api: Api | null } = { api: null };
 34	vi.mock("../sync/useApi.ts", () => ({ useApi: () => current.api }));
 35	
 36	/**
 37	 * A setup, and a shipped profile naming the tool it was written for.
 38	 *
 39	 * Neither ships for the demo pack: every setup in the repository is
 40	 * written for a tool this pack has never heard of, and a profile for it
 41	 * would be a file with nothing to say. So both are stood in for, and
 42	 * what is tested is the path from the offer to the run's record rather
 43	 * than what any particular tool does about it.
 44	 *
 45	 * The holder is hoisted because a mock factory is evaluated before this
 46	 * file's own body, and the pack's id is only known once it is loaded.
 47	 * Nothing reads it until an effect runs, by which time it is filled in.
 48	 */
 49	const stood = vi.hoisted(() => ({
 50	  pack: "",
 51	  tool: "DemoTool",
 52	  setup: {
 53	    kind: "setup" as const,
 54	    schemaVersion: 1,
 55	    id: "com.example.setups.starter",
 56	    version: "1.0.0",
 57	    title: "Starter",
 58	    tool: "DemoTool",
 59	    ops: [{ op: "player.give", args: { thing: "clay" } }],
 60	  },
 61	}));
